class Solution {
public:
    int countPrefixConnectedGroups(vector<string>& words, int k) {
        unordered_map<string, int> cnt;
        for (auto& w : words)
            if ((int)w.size() >= k) cnt[w.substr(0, k)]++;
        int ans = 0;
        for (auto& [p, c] : cnt) if (c >= 2) ans++;
        return ans;
    }
};

