class Solution {
    public int countPrefixConnectedGroups(String[] words, int k) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String w : words)
            if (w.length() >= k) cnt.merge(w.substring(0, k), 1, Integer::sum);
        int ans = 0;
        for (int v : cnt.values()) if (v >= 2) ans++;
        return ans;
    }
}

