class Solution {
public:
    int countPrefixConnectedGroups(vector<string>& words, int k) {
        vector<string> ws;
        for (auto& w : words) if ((int)w.size() >= k) ws.push_back(w.substr(0, k));
        sort(ws.begin(), ws.end());
        int ans = 0, i = 0;
        while (i < (int)ws.size()) {
            int j = i;
            while (j < (int)ws.size() && ws[j] == ws[i]) j++;
            if (j - i >= 2) ans++;
            i = j;
        }
        return ans;
    }
};

