        List<String> list = new ArrayList<>();
        for (String w : words) if (w.length() >= k) list.add(w.substring(0, k));
        Collections.sort(list);
        int ans = 0, i = 0;
        while (i < list.size()) {
            int j = i;
            while (j < list.size() && list.get(j).equals(list.get(i))) j++;
            if (j - i >= 2) ans++;
            i = j;
        }
        return ans;
    }
}

